sys_script_fix.script:
(function() {
    var tableName = 'x_431220_ciclo_iniciativa';
    var gr = new GlideRecord(tableName);
    gr.query();

    var count = 0;
    var appFileHandler = new GlideappApplicationFile();

    while (gr.next()) {
        // 1. Create the Application File (Metadata)
        appFileHandler.create(gr);

        // 2. Immediately find the Metadata record we just created
        // Record-based app files are stored in sys_app_data_file
        var metaGR = new GlideRecord('sys_app_data_file');
        metaGR.addQuery('record_id', gr.getUniqueValue());
        metaGR.query();

        if (metaGR.next()) {
            // 3. Flag it as Demo Data
            metaGR.demo_data = true; 
            metaGR.update();
        }

        count++;
        if (count % 500 === 0) {
            gs.info('Progress: ' + count + ' records marked as Demo Data...');
        }
    }

    gs.info('Success! ' + count + ' records are now officially Demo Data.');
})();
